-- Calls of SQL functions PostgreSQL inlines: polymorphic, in a MERGE or an
-- INSERT RETURNING, and with a user-type literal.
CREATE FUNCTION f891(integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$SELECT $1 + 1$$;
CREATE FUNCTION p891(anyelement) RETURNS anyelement LANGUAGE sql IMMUTABLE AS $$SELECT $1$$;
CREATE FUNCTION pa891(anyarray) RETURNS anyelement LANGUAGE sql IMMUTABLE AS $$SELECT $1[1]$$;
CREATE TYPE mood891 AS ENUM ('sad', 'ok');
CREATE FUNCTION m891(mood891) RETURNS integer LANGUAGE sql IMMUTABLE
  AS $$SELECT CASE WHEN $1 = 'ok' THEN 1 ELSE 0 END$$;
CREATE TABLE t891 (a integer, b integer);
CREATE TABLE u891 (x integer);
INSERT INTO t891 SELECT g, g % 5 FROM generate_series(1, 100) g;
INSERT INTO u891 SELECT g FROM generate_series(1, 50) g;
ANALYZE t891; ANALYZE u891;
EXPLAIN (VERBOSE, COSTS OFF) SELECT p891(a), pa891(ARRAY[a, b]) FROM t891;
EXPLAIN (VERBOSE, COSTS OFF) SELECT p891('x'::text), p891(1::bigint);
EXPLAIN (VERBOSE, COSTS OFF) SELECT m891('ok'), m891('sad'::mood891);
EXPLAIN (VERBOSE, COSTS OFF) INSERT INTO u891 VALUES (1) RETURNING f891(x);
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO u891 USING t891 ON u891.x = t891.a
  WHEN MATCHED THEN UPDATE SET x = f891(t891.b);
